from pathlib import Path
import re,hashlib,json
base=Path(__file__).resolve().parent;old=(base/'before-products.html').read_text();s=old
assert s.count('<main>')==1;s=s.replace('<main>','<main data-products-smart>',1)
hero=re.search(r'<section class="p-hero">(.*?)</section>',s,re.S);assert hero
art='<div class="p-smart-art" aria-hidden="true"><img class="p-smart-cover" src="/img/products/ai-learning-kit-600.webp" width="600" height="450" alt=""><img class="p-smart-cover" src="/img/products/content-creator-ai-pack-600.webp" width="600" height="450" alt=""><span class="p-smart-art-caption">LEARN · CREATE · BUILD</span></div>'
newhero='<section class="p-hero" aria-labelledby="products-title"><div class="p-smart-hero-copy"><span class="p-smart-kicker">AIUSEFLOW DIGITAL STORE · 11 PRODUCTS</span>'+hero[1].replace('<h1>','<h1 id="products-title">',1)+'<div class="p-smart-hero-links"><a class="p-smart-primary" href="#products-catalog">Find your next toolkit ↗</a><a href="/#free-tools">Looking for ₹0 utilities?</a></div></div>'+art+'</section><div class="p-smart-trust"><div><b>Made for practical work</b><span>Guides, prompts and templates for your next task.</span></div><div><b>Choose how you pay</b><span>UPI for India or PayPal for international orders.</span></div><div><b>Delivery after verification</b><span>Submit your transaction ID; receive the download link after payment confirmation.</span></div></div>'
s=s[:hero.start()]+newhero+s[hero.end():]
controls='''<p class="sub">Choose a goal, search what you need, or compare up to three products.</p><div class="p-smart-goals" aria-label="Find a product for your goal"><button type="button" data-product-goal="learn">I want to learn AI ↗</button><button type="button" data-product-goal="career">Find my next job ↗</button><button type="button" data-product-goal="creator">Create better content ↗</button><button type="button" data-product-goal="business">Grow my business ↗</button><button type="button" data-product-goal="coding">Build my first app ↗</button></div><section class="p-smart-controls" aria-label="Search and filter AIUseFlow products"><div class="p-smart-fields"><label for="product-search">What would you like to do?<input id="product-search" type="search" placeholder="Try resume, WhatsApp, prompts or coding" autocomplete="off"></label><label for="product-sort">Sort products<select id="product-sort"><option value="original">Original order</option><option value="low">INR price: low to high</option><option value="high">INR price: high to low</option></select></label></div><div class="p-smart-filter-row" role="group" aria-label="Product categories">'''
for k,t in [('all','All products'),('learn','Learning & prompts'),('career','Career'),('creator','Creators'),('business','Business'),('coding','Coding')]:controls+=f'<button type="button" data-store-category="{k}" aria-pressed="{str(k=="all").lower()}">{t}</button>'
controls+='''</div><div class="p-smart-results"><span role="status" data-store-status>11 products</span><button type="button" data-store-saved aria-pressed="false">♡ Saved products</button><button type="button" data-store-reset>Reset filters</button></div></section><div class="p-smart-compare-bar"><span data-compare-count>0 / 3 selected</span><button type="button" data-open-compare disabled>Compare selected</button><button type="button" data-clear-compare disabled>Clear selection</button><span role="status" data-compare-notice></span></div><div class="p-smart-empty" data-store-empty hidden><h3>No products match yet</h3><p>Try a shorter search, a different category, or reset the filters.</p></div>'''
s=s.replace('<h2>Our paid AI products</h2>','<h2 id="products-catalog">Our paid AI products</h2>'+controls,1)
start=s.index('<div class="sc-grid p-grid">');depth=0;end=None
for m in re.finditer(r'</?div\b[^>]*>',s[start:]):
 depth+=-1 if m[0].startswith('</') else 1
 if depth==0:end=start+m.end();break
assert end
support='''<div class="p-smart-motion-row"><button type="button" data-store-motion aria-pressed="false">Pause animation</button></div><section class="p-smart-support" aria-label="Ordering and product help"><div><h2>A clear path from choice to download.</h2><ol><li><strong>Explore the details.</strong> Read what is included and select the product that fits your goal.</li><li><strong>Choose UPI or PayPal.</strong> Review the displayed currency, price and terms in the existing checkout.</li><li><strong>Submit your transaction ID.</strong> Your download link is emailed after payment is confirmed.</li></ol><p>Need help choosing? <a href="mailto:contact@aiuseflow.com">contact@aiuseflow.com</a></p></div><div><h2>Before you order</h2><details><summary>Are the basic website tools still free?</summary><p>Yes. These paid products are optional. Basic <a href="/#free-tools">free utilities</a> remain ₹0 and do not automatically enroll you in a paid plan.</p></details><details><summary>Will I receive an instant download?</summary><p>Orders use payment verification. Submit the transaction ID in checkout; the download link is emailed after payment confirmation. Keep your order reference for support.</p></details><details><summary>How do membership prices work?</summary><p>The membership card displays a monthly price. Review its product details and checkout terms before deciding to pay. No new automatic subscription is activated by browsing or saving a product.</p></details><details><summary>Where can I check the refund policy?</summary><p>Read the <a href="/refund">refund policy</a> before ordering. For an existing order, email your order reference to <a href="mailto:contact@aiuseflow.com">contact@aiuseflow.com</a>. Never send passwords or full card details.</p></details><p>Want external AI tools instead? Browse <a href="#ai-free">AI Free</a> or <a href="#ai-plus">AI Plus</a> below.</p></div></section><dialog id="product-compare-dialog" aria-labelledby="product-compare-title"><div class="p-smart-dialog-head"><h2 id="product-compare-title">Compare your shortlist</h2><button type="button" data-close-compare>Close ×</button></div><div data-compare-table></div><p>Prices are shown as listed on each product card. Monthly memberships and per-participant training are different purchase types; compare the full terms rather than the amount alone. USD amounts are listed prices, not live exchange-rate conversions.</p></dialog>'''
s=s[:end]+support+s[end:]
version=hashlib.sha256((base/'store.css').read_bytes()+(base/'store.js').read_bytes()).hexdigest()[:12]
s=s.replace('</head>',f'<link rel="stylesheet" href="/assets/products-smart/store-{version}.css" data-products-smart-style></head>')
s=s.replace('</body>',f'<script src="/assets/products-smart/store-{version}.js" defer></script></body>')
assert len(re.findall(r'<article class="card sc-card p-card pe"',old))==11
for tag in re.findall(r'<script\b[^>]*>.*?</script>',old,re.S):assert tag in s
for href in re.findall(r'href="([^"]+)"',old):assert f'href="{href}"' in s
for img in re.findall(r'<img\b[^>]*>',old):assert img in s
for tag in re.findall(r'<title[^>]*>.*?</title>|<meta[^>]*name="description"[^>]*>|<link[^>]*rel="canonical"[^>]*>',old,re.S):assert tag in s
out=base/'release';out.mkdir(exist_ok=True);(out/'products.html').write_text(s)
for suffix,name in [('css','store.css'),('js','store.js')]: (out/f'store-{version}.{suffix}').write_bytes((base/name).read_bytes())
(base/'build-report.json').write_text(json.dumps({'version':version,'paid_products_preserved':11,'all_original_scripts_preserved':True,'all_original_links_preserved':True,'original_images_preserved':True,'seo_metadata_preserved':True,'database_changed':False,'checkout_changed':False,'new_subscriptions_activated':False},indent=2));print((base/'build-report.json').read_text())
